(() => {
  const totalSeconds =
    collections['45479114-dc05-4590-a6ea-0fb65d3f4087']?.data?.[0]?.elapsed_seconds; 
  const questionsTraitees =
    collections['f0dbe0d3-9fcc-4ea9-bfe9-1c5acebe76ba']?.data?.length|| 0;

  if (!totalSeconds || questionsTraitees === 0) {
    return 'Indisponible';
  }

  const avgSeconds = Math.floor(totalSeconds / questionsTraitees);

  const hours = Math.floor(avgSeconds / 3600);
  const minutes = Math.floor((avgSeconds % 3600) / 60);
  const seconds = avgSeconds % 60;

  const pad = n => String(n).padStart(2, '0');

  return `${pad(hours)} : ${pad(minutes)} : ${pad(seconds)}`;
})()

